struct MyResource {
    MyResource() { /* Setup */ }
    ~MyResource() { /* Cleanup */ }
    void run();
};

// 1. Creation and Scope Management
{
    auto p = std::make_unique<MyResource>();
    p->run();
    // Resource is automatically freed here (RAII)
}

// 2. Exclusive Ownership (Move, not Copy)
auto p1 = std::make_unique<MyResource>();
// auto p2 = p1;        // Compile Error: Non-copyable

auto p3 = std::move(p1); // Ownership transfer
// p1 is now nullptr
p3.release();            // Manual detachment (rare)
